INSERT INTO `scc_base_todolist_config` (`TODOLIST_CONFIG_ID`, `UNIQUE_CODE`, `CONFIG_MODULE`, `CONFIG_CODE`, `CONFIG_NAME`, `CONFIG_TYPE`, `CONFIG_FROM`, `CONFIG_VERSION`, `CONFIG_STATUS`, `ROLE_CODE`, `DIMENSION`, `CONFIG_MODE`, `SQL_LANGUAGE`, `URL_ADDRESS`, `URL_PARAMS`, `URL_MAPPING`, `FRONT_ROUTE_NAME`, `FRONT_FORM_NAME`, `FRONT_FUNCTION_NAME`, `CREATED_ID`, `CREATED_BY`, `CREATION_DATE`, `CREATED_BY_IP`, `CREATED_FULL_NAME`, `LAST_UPDATED_ID`, `LAST_UPDATED_BY`, `LAST_UPDATE_DATE`, `LAST_UPDATED_BY_IP`, `LAST_UPDATED_FULL_NAME`, `TENANT_ID`, `VERSION`) VALUES (462870606890880, 'CONTRACT_PEF_SCORE_DONE_FORM_PRODUCT_1000', 'CONTRACT_READ', 'CONTRACT_PEF_SCORE', '合同履约计划-履约阶段评分-已办', 'DONE_FORM', 'PRODUCT', 1000, 'Y', 'DATA_PERMISSION_ALL_BUYER', 'ALL', 'SQL', 'select * from ( SELECT \n p.PER_PLAN_ID AS businessId,\n p.PER_PLAN_NO AS businessCode,\n \'合同履约计划\' AS moduleName,\n \'/contractPerformance/contractPerformancePlan\' AS searchUrl,\n CONCAT(m.CREATED_FULL_NAME,\'(\',m.CREATED_BY,\')\') AS createName,\n CONCAT( \'【\',p.PER_PLAN_NO,\'-\',di.DICT_ITEM_NAME,\'】履约已评分\') AS title,\n m.CREATION_DATE AS creationDate,\n h.EXT_CONTRACT_HANDLER_ID,\n h.EXT_CONTRACT_HANDLER_NAME\n  FROM  meicloud_usrm_cloud_biz_contract.scc_cont_per_plan_milestone m \n  join meicloud_usrm_cloud_biz_contract.scc_cont_per_plan p ON m.PER_PLAN_ID = p.PER_PLAN_ID AND m.MILESTONE_TYPE = p.CURRENT_MILESTONE_TYPE\n  JOIN meicloud_usrm_cloud_biz_contract.scc_contract_head h ON h.CONTRACT_HEAD_ID = p.CONTRACT_HEAD_ID\n  JOIN meicloud_usrm_cloud_biz_contract.scc_contract_material cm ON h.CONTRACT_HEAD_ID = cm.CONTRACT_HEAD_ID\n  JOIN meicloud_usrm_cloud_biz_base.scc_base_dict_item di ON di.DICT_ITEM_CODE = m.MILESTONE_TYPE \n  JOIN meicloud_usrm_cloud_biz_base.scc_base_dict d ON d.DICT_ID = di.DICT_ID AND d.DICT_CODE = \'MILESTONE_SCHEDULE\' AND d.`LANGUAGE` =\'zh_CN\' \n	WHERE 1=1 AND \n	EXISTS(SELECT 1 FROM  meicloud_usrm_cloud_biz_performance.scc_npm_project_score_man sh \n	WHERE   sh.CONTRACT_NO = p.CONTRACT_NO AND sh.PERFORMANCE_CODE = m.MILESTONE_TYPE  AND sh.APPROVE_STATUS = \'Approved\' )\n	AND EXISTS( 	SELECT 1 FROM meicloud_usrm_cloud_biz_performance.scc_perf_template_category tc \n		INNER JOIN meicloud_usrm_cloud_biz_performance.scc_perf_template_header th ON tc.TEMPLATE_HEAD_ID = th.TEMPLATE_HEAD_ID\n		WHERE 1=1 AND th.TEMPLATE_STATUS = \'VALID\' AND tc.CATEGORY_ID = cm.CATEGORY_ID AND th.ATTRIBUTE1 = \'PROJECT\' )\n	AND m.EXT_CREATE_PERFORM_FLAG = \'Y\' AND (h.EXT_EVALUATE_FLAG IS NULL OR h.EXT_EVALUATE_FLAG = \'N\') 	\n	#AND h.EXT_CONTRACT_HANDLER_ID = ${user.userId}\n) t', NULL, NULL, NULL, NULL, NULL, NULL, 8123195817787648, 'super', '2024-01-25 18:11:44', '10.254.103.203', '超级管理员', NULL, NULL, '2024-01-25 18:11:44', '10.254.103.203', '超级管理员', NULL, 0);
