INSERT INTO `scc_base_todolist_config` (`TODOLIST_CONFIG_ID`, `UNIQUE_CODE`, `CONFIG_MODULE`, `CONFIG_CODE`, `CONFIG_NAME`, `CONFIG_TYPE`, `CONFIG_FROM`, `CONFIG_VERSION`, `CONFIG_STATUS`, `ROLE_CODE`, `DIMENSION`, `CONFIG_MODE`, `SQL_LANGUAGE`, `URL_ADDRESS`, `URL_PARAMS`, `URL_MAPPING`, `FRONT_ROUTE_NAME`, `FRONT_FORM_NAME`, `FRONT_FUNCTION_NAME`, `CREATED_ID`, `CREATED_BY`, `CREATION_DATE`, `CREATED_BY_IP`, `CREATED_FULL_NAME`, `LAST_UPDATED_ID`, `LAST_UPDATED_BY`, `LAST_UPDATE_DATE`, `LAST_UPDATED_BY_IP`, `LAST_UPDATED_FULL_NAME`, `TENANT_ID`, `VERSION`) VALUES (462496672437376, 'CONTRACT_BID_NOTICE_EDIT_WAIT_FORM_PRODUCT_1000', 'CONTRACT_READ', 'CONTRACT_BID_NOTICE_EDIT', '合同管理-中落标创建编辑-待办', 'WAIT_FORM', 'PRODUCT', 1000, 'Y', 'DATA_PERMISSION_ALL_BUYER', 'ALL', 'SQL', 'SELECT * FROM (SELECT \n h.CONTRACT_HEAD_ID AS businessId, \n h.CONTRACT_NO AS businessCode,\n \'合同管理列表\' AS moduleName,\n CONCAT(\'【\',h.CONTRACT_NO,\'】中落标创建合同待编辑提交,请及时处理\') AS title,\n \'/contractManagement/contractMaintainList\' AS searchUrl,\n CONCAT(h.CREATED_FULL_NAME,\'(\',h.CREATED_BY,\')\') AS createName,\n h.CREATION_DATE AS creationDate\n 		FROM scc_contract_head h \n WHERE h.SOURCE_TYPE = \'BID_NOTICE\' \nAND h.CONTRACT_STATUS = \'DRAFT\' \nAND h.EXT_CONTRACT_HANDLER_ID = ${user.userId} \n) t', NULL, NULL, NULL, NULL, NULL, NULL, 8123195817787648, 'super', '2024-01-23 15:28:39', '10.254.103.203', '超级管理员', 8123195817787648, 'super', '2024-01-23 18:07:06', '10.254.103.203', '超级管理员', NULL, 0);
